const rl = require('readline-sync')

let notaparcial1 = parseFloat(rl.question("Ingrese la nota del parcial: "))
let notaparcial2 = parseFloat(rl.question("Ingrese la nota del parcial: "))
let notaparcial3 = parseFloat(rl.question("Ingrese la nota del parcial: "))

let examenfinal = parseFloat(rl.question("Ingrese la nota del examen final: "))
let notatrabajofinal = parseFloat(rl.question("Ingrese la nota del trabajo final: "))

let notaparciales = (notaparcial1 + notaparcial2 + notaparcial3) / 3
let notafinal = notaparciales * 0.55 + examenfinal * 0.30 + notatrabajofinal * 0.15

console.log("La nota final es: " + notafinal.toFixed(2))
